/**
  Annotations
*/
p em {
  background: unset !important;
}
.annotate-box {
  position: absolute;
  padding: 16px;
  background-color: #FFF;
  box-shadow: 0 4px 6px #333;
  border-radius: 2px;
  height: 72px;
  width: 200px;
}
.annotate-box h3 {
  font-size: 14px;
  font-weight: 500;
  font-family: 'Helvetica Neue, Segoe UI, san-serif';
  color: #484848;
}
.annotation-data-view.ql-editor::-webkit-scrollbar {
  width: 3px;
}
.annotate-target {
  color: #FFF;
  background-color: #03A9F4;
  height: 21px;
  width: 21px;
  border-radius: 100px;
  position: absolute;
  border: 2px #5cb7f3 solid;
  font-family: 'Helvetica Neue, Segoe UI, san-serif';
  font-size: 12px;
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
}
.drag-annotation {
  align-items: unset !important;
  justify-content: unset !important;
  padding: 16px !important;
  padding: 20px 10px !important;
  display: flex;
  align-items: center;
  justify-content: center;
  border: solid 1px #ddd;
  background: #f0f0f0;
  position: absolute;
  z-index: 111;
  box-shadow: #cccccc 0px 0px 2px 0px;
  border: 2px;
  border-radius: 2px;
}
.drag-annotation .mention {
  height: unset;
  width: unset;
  border-radius: unset;
  background-color: unset;
  padding: unset;
  margin-right: unset;
}
.drop-down-container {
  display: flex;
  align-items: center;
  flex: 0 0 100%;
  margin-bottom: 16px;
  justify-content: flex-end;
}
.drop-down-wrapper {
  position: relative;
  width: 150px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
}
.drag-annotation .menu-item,
.table-popup .menu-item {
  display: none;
  position: absolute;
  top: 5px;
  right: 0px;
  /* display: flex; */
  align-items: center;
  justify-content: center;
}
.drag-annotation .menu-item i,
.table-popup .menu-item i {
  margin: 0 4px ;
  z-index: 13;
  cursor: pointer;
  /* color: var(--class-item-bg); */
  /* filter: invert(80%); */
}
.table-popup .menu-item {
  right: 12px;
}
.table-popup .menu-item:first-child i {
  margin: 0 8px 0 0 ;
}
.table-popup .menu-item i {
  margin: 0 4px 0 0 ;
}
.drag-annotation .menu-item.dark i,
.table-popup .menu-item.dark i {
  color: #fff;
}
.drag-annotation .menu-item.light i,
.table-popup .menu-item.light i {
  color: #666666;
}
.drag-annotation-point {
  background-color: transparent !important;
  border: unset !important;
  display: flex;
  align-items: center;
  justify-content: center;
  border: solid 1px #ddd;
  background: "#f0f0f0";
  position: "absolute";
}
.annotation-context-menu-container {
  background-color: #fff;
  background-clip: padding-box;
  border: 1px solid rgba(0, 0, 0, 0.15);
  border-radius: 0;
  color: #414141;
  font-size: 13px;
  margin: 2px 0 0;
  min-width: 145px;
  opacity: 0;
  padding: 5px 0;
  text-align: left;
  transition: opacity 250ms ease !important;
}
.annotation-context-menu-container .menu-item {
  background: 0 0;
  border: 0;
  color: #373a3c;
  font-weight: 400;
  line-height: 1.5;
  padding: 3px 16px;
  text-align: inherit;
  white-space: nowrap;
  cursor: pointer;
}
.annotation-context-menu-container .menu-item:hover {
  color: #20a0ff;
  text-decoration: none;
}
.drag-comp-container {
  position: absolute;
  top: 0;
}
.drag-comp-container .arrow-container {
  position: absolute;
  width: 11px;
  z-index: 12;
  transform-origin: top;
}
.drag-annotation-point .target-point {
  border-radius: 50%;
  color: #fff;
  z-index: 12;
  display: flex;
  justify-content: center;
  align-items: center;
}
.drag-annotation-point .target-point.table {
  border-style: solid;
  border-width: 0px 11px 11px 11px;
  height: 0px;
  width: 0px;
  border-radius: 0;
  -webkit-transform: rotate(45deg);
  transform: rotate(45deg);
}
.drag-annotation-point .target-point.table.rotate {
  -webkit-transform: rotate(-45deg);
  transform: rotate(-45deg);
  position: absolute;
  left: -6px;
}
.drag-annotation .annotation-data-view {
  height: 100%;
  width: 100%;
  overflow: auto;
}
.drag-annotation .ql-editor,
.table-popup .ql-editor {
  padding: unset;
}
.drag-annotation:hover .menu-item,
.table-popup:hover .menu-item {
  display: flex;
}
.drag-annotation .ql-editor,
.annotation-wrapped-container .quill,
.table-popup .ql-editor {
  font-size: 14px;
}
.drag-annotation .ql-editor p,
.annotation-wrapped-container .quill .ql-editor p,
.table-popup .ql-editor p {
  font-size: 12px;
  font-weight: inherit;
  line-height: 1.1;
}
.dummy-div {
  position: absolute;
  user-select: auto;
  touch-action: none;
  display: inline-block;
  top: 0px;
  left: 0px;
  cursor: move;
  flex-direction: column;
  visibility: hidden;
  background-color: #ffffff;
  opacity: 1;
  max-width: 300px;
  max-height: 24.0072e;
  min-width: 100px;
  box-sizing: border-box;
  flex-shrink: 0;
}
/* Indicators */
.indicator-container .indicator-div {
  width: 100%;
  height: 100%;
  font-size: 10px;
  line-height: 13px;
}
/* .indicator-container .indicator-div span {
  font-size: 20px;
  line-height: 13px;
} */
.indicator-container .indicator-div.circle {
  border-radius: 50%;
