}
.icon-annotation {
  color: #212121;
}

/* 
  Modal.scss 
  - Includes all default styles for the Modal component
*/
.modal {
  align-items: center;
  bottom: 0;
  display: none;
  justify-content: center;
  left: 0;
  opacity: 0;
  overflow: hidden;
  padding: 0.4rem;
  position: fixed;
  right: 0;
  top: 0;
}
.modal:target,
.modal.active {
  display: flex;
  opacity: 1;
  z-index: 400;
}
.modal:target .modal-overlay,
.modal.active .modal-overlay {
  background: rgba(255, 255, 255, 0.75);
  bottom: 0;
  cursor: default;
  display: block;
  left: 0;
  position: absolute;
  right: 0;
  top: 0;
}
.modal:target .modal-container,
.modal.active .modal-container {
  animation: slide-down 0.2s ease 1;
  z-index: 1;
}
.modal.modal-sm .modal-container {
  max-width: 320px;
}
.modal.modal-lg .modal-overlay {
  background: #f4f4f4;
}
.modal.modal-lg .modal-container {
  box-shadow: none;
  max-width: 960px;
}
.modal-container {
  box-shadow: 0 0.2rem 0.5rem rgba(33, 33, 33, 0.3);
  background: #ffffff;
  border-radius: 0.1rem;
  display: flex;
  flex-direction: column;
  max-height: 75vh;
  max-width: 640px;
  padding: 0;
  width: 100%;
}
.modal-container.modal-fullheight {
  max-height: 100vh;
}
.modal-container .modal-header {
  color: #212121;
  padding: 0.4rem 0.6rem;
  border-bottom: 1px #dbdbdb solid;
}
.modal-container .modal-header .btn-close {
  background: none;
  border: 0;
  outline: 0;
}
.modal-container .modal-header h4 {
  font-size: 13px;
  margin: 0;
}
.modal-container .modal-body {
  overflow-y: auto;
  padding: 0.8rem;
  position: relative;
}
.modal-container .modal-footer {
  padding: 0.8rem;
  text-align: right;
}

/* 
  Button.scss 
  - Includes all default styles for the button component
*/
.btn {
  position: relative;
  -webkit-font-smoothing: antialiased;
  background-color: #f4f4f4;
  border: none;
  color: #333333;
  font-size: 13px;
  font-weight: 600;
  box-sizing: border-box;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  vertical-align: top;
  padding-top: 0;
  padding-right: 0.8rem;
  padding-left: 0.8rem;
  padding-bottom: 0;
  display: inline-block;
  height: 1.8rem;
  min-width: 4rem;
  line-height: 1.2rem;
  outline: transparent;
  border: 0.05rem solid transparent;
  border-image: initial;
  border-radius: 0;
  user-select: none;
  white-space: nowrap;
}
.btn:focus,
.btn:hover {
  background: #dbdbdb;
  text-decoration: none;
}
.btn[disabled],
.btn:disabled,
.btn.disabled {
  cursor: default;
  opacity: 0.5;
  pointer-events: none;
}
.btn.btn-primary {
  background-color: #f2c811;
  color: #212121;
}
.btn.btn-primary:focus,
.btn.btn-primary:hover {
  background: #ddb60c;
}
.btn.btn-secondary {
  background-color: #0078d4;
  color: #f4f4f4;
}
.btn.btn-secondary:focus,
.btn.btn-secondary:hover {
  background: #006abb;
}
.btn.btn-disabled {
  background-color: #f4f4f4;
  color: #a6a6a6;
}
.btn.btn-disabled:focus,
.btn.btn-disabled:hover {
  cursor: default;
  background: #e7e7e7;
}
.btn.btn-action {
  background-color: #212121;
  color: #f4f4f4;
}
.btn.btn-action:focus,
.btn.btn-action:hover {
  background: #2e2e2e;
}
.btn.btn-success {
  background: #bad80a;
  border-color: #adc909;
  color: #f4f4f4;
