  background: #f7f7f7;
}
.form-radio .form-icon {
  border-radius: 50%;
}
.form-radio input:checked + .form-icon::before {
  background: #0078d4;
  border-radius: 50%;
  content: "";
  height: 8px;
  left: 50%;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 8px;
}
.has-error .form-radio .form-icon,
.form-radio.is-error .form-icon {
  border-color: #e81123;
}
