*/
.form-switch {
  font-size: 0.6rem;
  min-width: 48px;
  display: block;
  line-height: 1.3rem;
  margin: 0.2rem 0;
  min-height: 1.2rem;
  padding: 0.1rem 0.4rem 0.1rem 1.2rem;
  position: relative;
}
.form-switch input {
  clip: rect(0, 0, 0, 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  position: absolute;
  width: 1px;
}
.form-switch input:focus + .form-icon {
  border-color: #a6a6a6;
}
